#!/usr/bin/env node
/**
 * Sync the federation contract artifact into this SDK's vendored copy (DEVX-S0, ADR-0001).
 *
 * Source of truth:
 *   citrate-federation/contract/federation-contract.json
 * generated by:
 *   citrate-federation/scripts/gen-contract.mjs (from citrate-chain 40204.json + citrate-identity)
 *
 *   npm run sync-contract          # overwrite the vendored copy
 *   npm run verify:contract        # CI gate: non-zero if vendored copy drifted
 */
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = resolve(__dirname, '..');
const LABS_ROOT = resolve(REPO_ROOT, '..');
const CANONICAL = resolve(LABS_ROOT, 'citrate-federation', 'contract', 'federation-contract.json');
const VENDORED = resolve(REPO_ROOT, 'src', 'generated', 'federation-contract.json');

const CHECK = process.argv.includes('--check');

if (!existsSync(CANONICAL)) {
  console.error(`[sync-contract] canonical not found at ${CANONICAL}\n` +
    '  Ensure citrate-federation is a sibling of this repo under citrate-labs/, and run\n' +
    '  `node scripts/gen-contract.mjs` there first.');
  process.exit(CHECK ? 1 : 1);
}

const canonical = JSON.parse(readFileSync(CANONICAL, 'utf8'));
if (canonical.schemaVersion !== 1) { console.error(`[sync-contract] unexpected schemaVersion ${canonical.schemaVersion}`); process.exit(1); }
if (canonical.chain?.chainId !== 40204) { console.error(`[sync-contract] chainId ${canonical.chain?.chainId}, expected 40204`); process.exit(1); }

const serialized = JSON.stringify(canonical, null, 2) + '\n';

if (CHECK) {
  if (!existsSync(VENDORED)) { console.error(`[sync-contract] no vendored copy at ${VENDORED}`); process.exit(1); }
  if (readFileSync(VENDORED, 'utf8') !== serialized) {
    console.error('[sync-contract] vendored federation-contract.json is OUT OF SYNC. Run `npm run sync-contract` and commit.');
    process.exit(1);
  }
  console.log('[sync-contract] vendored contract matches canonical ✓');
  process.exit(0);
}

writeFileSync(VENDORED, serialized);
console.log(`[sync-contract] wrote ${VENDORED} (EntryPoint ${canonical.aaStack.EntryPoint})`);
